    )
    update_metadata = {
        "source": "harbor-history-audit",
        "run_id": run_id,
        "profile_seed": True,
        "audit_update": True,
        "changed_field": "job_seniority",
        "previous_memory_text": old_text,
    }
    client.update(memory_id=memory_id, text=updated_text, metadata=update_metadata)

